__NUXT_JSONP__("/finanzas-publicas/eventos/los_sistemas_estatales_anticorrupcion_operan_con_avances_desiguales", (function(a,b,c,d,e){return {data:[{post:{slug:"los_sistemas_estatales_anticorrupcion_operan_con_avances_desiguales",title:"Los Sistemas Estatales Anticorrupción operan con avances desiguales",date:"2026-01-06T18:24:00.000Z",img:"https:\u002F\u002F429spfvz9e.ucarecd.net\u002F6a40107d-fa5f-4d10-892f-785715a43cd4\u002F","img-alt":"Sistemas Estatales Anticorrupción",autor:"Ethos",category:"finanzas-publicas",extracto:"Emiliano Montes de Oca, coordinador de participación ciudadana y proyectos anticorrupción en Ethos, señaló que el avance de los Sistemas Estatales Anticorrupción en México enfrenta rezagos en designaciones, presupuesto y operación.",toc:[],body:{type:"root",children:[{type:b,tag:c,props:{},children:[{type:a,value:"El desarrollo de los Sistemas Estatales Anticorrupción (SEA) en México es profundamente desigual. Mientras algunas entidades avanzan en legislación, designaciones, políticas anticorrupción y asignación presupuestal, otras operan de manera incompleta, sin recursos para sus integrantes o, en los casos más graves, simplemente no existen."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Así lo señaló Emiliano Montes de Oca, coordinador de participación ciudadana y proyectos anticorrupción en Ethos Innovación en Políticas Públicas, durante una conferencia organizada por la Secretaría Ejecutiva del Sistema Anticorrupción del Estado de Coahuila, en el marco del Día Internacional contra la Corrupción. En su intervención, expuso algunos de los principales pendientes en la lucha anticorrupción en el país."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"De acuerdo con información reportada al 30 de septiembre de 2025 por la Secretaría Ejecutiva del Sistema Nacional Anticorrupción (SESNA), de los 770 integrantes que deben conformar en conjunto los Sistemas Estatales Anticorrupción, 271 designaciones permanecían pendientes, lo que equivale a 35%. En el caso de los Comités de Participación Ciudadana (CPC), el rezago es aún mayor: 47% de los nombramientos no se han realizado."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"En cuanto a las Secretarías Ejecutivas, Montes de Oca detalló que en 12 estados sigue pendiente la designación de sus titulares. Solo siete SEA cuentan con la totalidad de sus integrantes: Baja California Sur, Coahuila, Guanajuato, Jalisco, Quintana Roo, Sinaloa y Yucatán. En contraste, 35% de los sistemas estatales opera con menos de la mitad de sus designaciones completas, entre ellos Campeche, Colima, Ciudad de México, Guerrero, Hidalgo, Michoacán, Morelos, Nayarit, Querétaro, Sonora y Veracruz."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Sobre el panorama general del Sistema Nacional Anticorrupción (SNA), advirtió que se encuentra debilitado, tanto por las amenazas de desaparición como por los conflictos internos y la falta de resultados tangibles en varios de sus componentes."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Ante este escenario, explicó que desde los CPC y la sociedad civil organizada se ha planteado una propuesta de reforma que abre la posibilidad de reactivar el sistema y hacerlo más eficaz. Sin embargo, aunque se han planteado diversas propuestas para la reforma, todavía no existe un consenso claro sobre los cambios que debería incorporar."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"“Es necesario abrir el diálogo con autoridades, sociedad civil, academia y ciudadanía para recuperar todas las voces y devolverle vida al SNA o, incluso, plantear un nuevo mecanismo si así se requiere. Pero debemos actuar con urgencia, porque la corrupción sigue siendo, por mucho, una tarea pendiente”, concluyó."}]}]},dir:"\u002Feventos",path:"\u002Feventos\u002Flos_sistemas_estatales_anticorrupcion_operan_con_avances_desiguales",extension:".md",createdAt:e,updatedAt:e}}],fetch:{},mutations:[]}}("text","element","p","\n","2026-07-19T00:56:17.213Z")));